// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.gDepCd;
scwin.gIsurCd;
scwin.gPrtdepoEndDd;
scwin.gPrtdepoId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        if (js_market === "1" || js_market === "2" || js_market === "6") {
            $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
            rdo_MARKET_TP_CD.setValue(js_market);
            panel_mkt_gubun.hide();
        } else {
            panel_mkt_gubun.show("");
        }
        if (js_market === "2") {
            $c.cm.setColumnProp(grd_List, "INPROSPCTS_EXST_STRT_DD", "Show", false);
            $c.cm.setColumnProp(grd_List, "ISUR_SYMBL", "Show", false);
        }
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setCode();
        scwin.listSync();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40207.onpageload" });
    }
};

/**
 * @method
