 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40207.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Indp_OnLoadCompleted
 * @description dts_Indp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Indp_OnLoadCompleted = function(rowcount) {
    try {
        dts_Indp.insertRow(0);
        dts_Indp.setCellData(1, "VALUE", "");
        dts_Indp.setCellData(1, "TEXT", "전체");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40207.dts_Indp_OnLoadCompleted" });
    }
};

/**
