scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    const url = "/listingCommon.do?SCREN_ID=" + "ULDSTF40207.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PROTECTED_DEPOSITION_ADMINISTRATIVE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.prtdepomgt.prtdepo_rto_adm" + "&{P}param01=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param02=" + rdo_MARKET_TP_CD.getValue() + // 시장구분
        "&{P}param03=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param04=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param05=" + edt_EDate.getValue(); // 종료일자

    /*
    			"&{P}param03=" + getObjectValue(txb_ISUR_CD) + // 법인코드
    			"&{P}param04=" + getObjectValue(txb_ISUR_CD) + // 법인코드

    			"&{P}param05=" + getObjectValue(edt_SDate) + // 시작일자
    			"&{P}param06=" + getObjectValue(edt_EDate); // 종료일자
     */

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};

/**
 * @method
 * @name setId
 * @description set Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name getId
 * @description get Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getId = function() {
    return scwin.gIsurCd;
};

/**
